-- Upgrade migration: make admission approval use the current academic-year batch
-- and a per-account temporary password hash generated by the authenticated API.
-- No table/data changes are made. Apply this file to an existing database after
-- deploying the matching backend, or use the updated database/05_procedures.sql
-- when creating a fresh database.
SET NAMES utf8mb4;
DROP PROCEDURE IF EXISTS `sp_approve_admission`;
DELIMITER $$
CREATE PROCEDURE `sp_approve_admission`(
  IN  p_admission_id  INT UNSIGNED,
  IN  p_reviewed_by   INT UNSIGNED,
  IN  p_approve       TINYINT,
  IN  p_remarks       VARCHAR(500),
  IN  p_password_hash VARCHAR(255),
  OUT p_student_id    INT UNSIGNED,
  OUT p_message       VARCHAR(255)
)
BEGIN
  DECLARE v_app             VARCHAR(30) DEFAULT NULL;
  DECLARE v_first           VARCHAR(80) DEFAULT NULL;
  DECLARE v_last            VARCHAR(80) DEFAULT NULL;
  DECLARE v_email           VARCHAR(150) DEFAULT NULL;
  DECLARE v_phone           VARCHAR(20) DEFAULT NULL;
  DECLARE v_dob             DATE DEFAULT NULL;
  DECLARE v_gender          VARCHAR(10) DEFAULT NULL;
  DECLARE v_prog            SMALLINT UNSIGNED DEFAULT NULL;
  DECLARE v_cat             TINYINT UNSIGNED DEFAULT NULL;
  DECLARE v_year            SMALLINT UNSIGNED DEFAULT NULL;
  DECLARE v_guardian        VARCHAR(120) DEFAULT NULL;
  DECLARE v_gphone          VARCHAR(20) DEFAULT NULL;
  DECLARE v_admission_state VARCHAR(20) DEFAULT NULL;
  DECLARE v_dept            INT UNSIGNED DEFAULT NULL;
  DECLARE v_batch           SMALLINT UNSIGNED DEFAULT NULL;
  DECLARE v_admission_year  SMALLINT UNSIGNED DEFAULT NULL;
  DECLARE v_role            TINYINT UNSIGNED DEFAULT NULL;
  DECLARE v_user            INT UNSIGNED DEFAULT NULL;
  DECLARE v_roll            VARCHAR(20) DEFAULT NULL;
  DECLARE v_regno           VARCHAR(30) DEFAULT NULL;
  DECLARE v_program_code    VARCHAR(20) DEFAULT NULL;
  DECLARE v_program_tag     VARCHAR(20) DEFAULT NULL;
  DECLARE v_seq             INT DEFAULT NULL;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET p_student_id = NULL;
  SET p_message = NULL;

  IF p_approve NOT IN (0, 1) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid admission decision.';
  END IF;

  START TRANSACTION;

  SELECT `application_no`, `first_name`, `last_name`, `email`, `phone`, `date_of_birth`,
         `gender`, `program_id`, `category_id`, `academic_year_id`, `guardian_name`,
         `guardian_phone`, `status`, `student_id`
    INTO v_app, v_first, v_last, v_email, v_phone, v_dob, v_gender, v_prog, v_cat,
         v_year, v_guardian, v_gphone, v_admission_state, p_student_id
  FROM `admissions`
  WHERE `admission_id` = p_admission_id
  FOR UPDATE;

  IF v_app IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Admission application not found.';
  END IF;

  IF v_admission_state NOT IN ('APPLIED', 'UNDER_REVIEW', 'WAITLISTED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This application has already been reviewed.';
  END IF;

  IF p_approve = 0 THEN
    UPDATE `admissions`
    SET `status` = 'REJECTED', `reviewed_by` = p_reviewed_by,
        `reviewed_at` = NOW(), `remarks` = p_remarks
    WHERE `admission_id` = p_admission_id;

    INSERT INTO `audit_logs` (`user_id`, `action`, `entity`, `entity_id`, `description`)
    VALUES (p_reviewed_by, 'REJECT', 'admissions', p_admission_id,
            CONCAT('Admission ', v_app, ' rejected'));

    SET p_message = 'Application rejected.';
    COMMIT;
  ELSE
    IF p_student_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'This application has already been converted into a student.';
    END IF;
    IF p_password_hash IS NULL OR CHAR_LENGTH(p_password_hash) < 20 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A valid temporary password hash is required.';
    END IF;

    SELECT `department_id`, `program_code`
      INTO v_dept, v_program_code
    FROM `programs`
    WHERE `program_id` = v_prog;

    IF v_dept IS NULL OR v_program_code IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The selected program is no longer available.';
    END IF;

    SELECT `batch_id`, `start_year`
      INTO v_batch, v_admission_year
    FROM `batches`
    WHERE `program_id` = v_prog AND `academic_year_id` = v_year AND `status` = 'ACTIVE'
    ORDER BY `batch_id` ASC
    LIMIT 1
    FOR UPDATE;

    IF v_batch IS NULL OR v_admission_year IS NULL THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No batch exists for this program and academic year.';
    END IF;

    SELECT `role_id` INTO v_role FROM `roles` WHERE `role_code` = 'STUDENT' LIMIT 1;
    IF v_role IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The student role is not configured.';
    END IF;

    IF EXISTS (SELECT 1 FROM `users` WHERE `email` = v_email) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A user with this email already exists.';
    END IF;

    INSERT INTO `users`
      (`role_id`, `email`, `password_hash`, `phone`, `is_active`, `is_first_login`)
    VALUES (v_role, LOWER(TRIM(v_email)), p_password_hash, v_phone, 1, 1);
    SET v_user = LAST_INSERT_ID();

    SELECT COALESCE(MAX(CAST(RIGHT(`roll_number`, 4) AS UNSIGNED)), 1000) + 1
      INTO v_seq
    FROM `students`
    WHERE `admission_year` = v_admission_year AND `program_id` = v_prog;

    SET v_program_tag = REPLACE(REPLACE(v_program_code, 'BTECH-', ''), 'MTECH-', 'M');
    SET v_roll = CONCAT(v_admission_year, v_program_tag, LPAD(v_seq, 4, '0'));
    SET v_regno = CONCAT('PICT/', v_admission_year, '/', v_program_tag, '/', LPAD(v_seq, 4, '0'));

    INSERT INTO `students`
      (`user_id`, `roll_number`, `registration_number`, `first_name`, `last_name`, `email`,
       `phone`, `date_of_birth`, `gender`, `category_id`, `department_id`, `program_id`,
       `batch_id`, `admission_year`, `admission_date`, `current_semester_no`, `status`)
    VALUES
      (v_user, v_roll, v_regno, v_first, v_last, LOWER(TRIM(v_email)), v_phone, v_dob, v_gender,
       v_cat, v_dept, v_prog, v_batch, v_admission_year, CURDATE(), 1, 'ACTIVE');

    SET p_student_id = LAST_INSERT_ID();

    INSERT INTO `guardians` (`student_id`, `name`, `relation`, `phone`, `is_primary`)
    VALUES (p_student_id, v_guardian, 'FATHER', v_gphone, 1);

    UPDATE `admissions`
    SET `status` = 'APPROVED', `student_id` = p_student_id, `reviewed_by` = p_reviewed_by,
        `reviewed_at` = NOW(), `remarks` = IFNULL(p_remarks, 'Approved')
    WHERE `admission_id` = p_admission_id;

    INSERT INTO `audit_logs` (`user_id`, `action`, `entity`, `entity_id`, `description`)
    VALUES (p_reviewed_by, 'APPROVE', 'admissions', p_admission_id,
            CONCAT('Admission approved - student ', v_roll, ' created'));

    CALL sp_push_notification(v_user, 'Admission approved',
      CONCAT('Your application has been approved. Your roll number is ', v_roll, '.'),
      'ADMISSION', 'SUCCESS', 'student', p_student_id, '/profile');

    SET p_message = CONCAT('Admission approved. Student ', v_roll, ' created.');
    COMMIT;
  END IF;
END$$
DELIMITER ;
